def icon(name: str, size: int = 16, *, cls: str = "") -> str:
    """Return an inline ``<svg>`` for ``name`` (falls back to an info icon)."""
    body = _PATHS.get(name, _PATHS["info"])
    c = f' class="ic {cls}"' if cls else ' class="ic"'
    return (f'<svg{c} width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">{body}</svg>')
